node --input-type=module -e "
import { backoffDelay } from './src/retry.js';
const N = 100000;
for (const a of [0,1,2,3,5,6,10]) {
  let neg=0, over=0, min=Infinity, max=-Infinity;
  for (let i=0;i<N;i++){ const d=backoffDelay(a); if(d<=0)neg++; if(d>10000)over++; min=Math.min(min,d); max=Math.max(max,d); }
  console.log('attempt',a,'min',min.toFixed(0),'max',max.toFixed(0),'<=0:',(100*neg/N).toFixed(1)+'%','>cap:',(100*over/N).toFixed(1)+'%');
}
" && node --test test/ 2>&1 | tail -8
